testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validarProduto } from './solution.mjs';

test('dados válidos liberam o produto, com nome sem espaços extras', () => {
  const resultado = validarProduto({ nome: '  Caneca  ', preco: 19.9 });
  assert.equal(resultado.ok, true);
  assert.deepEqual(resultado.produto, { nome: 'Caneca', preco: 19.9 });
});

test('produto com categoria válida mantém a categoria limpa', () => {
  const resultado = validarProduto({ nome: 'Caneca', preco: 10, categoria: '  Casa  ' });
  assert.deepEqual(resultado.produto, { nome: 'Caneca', preco: 10, categoria: 'Casa' });
});

test('nome vazio ou faltando é recusado com mensagem clara', () => {
  const resultado = validarProduto({ preco: 5 });
  assert.equal(resultado.ok, false);
  assert.ok(resultado.erros.includes('nome é obrigatório'));
});

test('preço inválido ou categoria vazia também são recusados', () => {
  const semPreco = validarProduto({ nome: 'Caneca' });
  assert.ok(semPreco.erros.includes('preco deve ser um número maior ou igual a zero'));

  const precoNegativo = validarProduto({ nome: 'Caneca', preco: -1 });
  assert.ok(precoNegativo.erros.includes('preco deve ser um número maior ou igual a zero'));

  const categoriaVazia = validarProduto({ nome: 'Caneca', preco: 5, categoria: '   ' });
  assert.ok(categoriaVazia.erros.includes('categoria deve ser um texto'));
});

solutionCode:
export function validarProduto(dados) {
  const erros = [];

  if (typeof dados?.nome !== 'string' || dados.nome.trim() === '') {
    erros.push('nome é obrigatório');
  }
  if (typeof dados?.preco !== 'number' || !Number.isFinite(dados.preco) || dados.preco < 0) {
    erros.push('preco deve ser um número maior ou igual a zero');
  }
  if (dados?.categoria !== undefined && (typeof dados.categoria !== 'string' || dados.categoria.trim() === '')) {
    erros.push('categoria deve ser um texto');
  }

  if (erros.length > 0) return { ok: false, erros };

  const produto = { nome: dados.nome.trim(), preco: dados.preco };
  if (typeof dados.categoria === 'string') {
    produto.categoria = dados.categoria.trim();
  }
  return { ok: true, produto };
}
